it 'replaces the inline form for turbo stream requests' do
  post :create, params: { todo_list: { name: 'New List' } }, format: :turbo_stream

  expect(response.media_type).to eq(Mime[:turbo_stream].to_s)
  expect(response).to render_template(:create)
  expect(assigns(:todo_list)).to be_a_new(TodoList)
end

# POST /todolists
def create
  @todo_list = TodoList.new(todo_list_params)
  status = @todo_list.save ? :ok : :unprocessable_entity
  @todo_list = TodoList.new if @todo_list.persisted?

  respond_to do |format|
    format.turbo_stream { render status: status }
  end
end

